<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,useId} from 'vue';
const props=defineProps<{modelValue:string;options:{id:string;title:string;depth:number;is_folder:boolean}[];disabled?:boolean}>();
const emit=defineEmits<{'update:modelValue':[id:string]}>();
const open=ref(false),root=ref<HTMLElement|null>(null),trigger=ref<HTMLButtonElement|null>(null),list=ref<HTMLElement|null>(null);const id=useId();
const selected=computed(()=>props.options.find(o=>o.id===props.modelValue)?.title||'空白文章');
function close(focus=false){open.value=false;if(focus)trigger.value?.focus();}
async function show(){if(props.disabled)return;open.value=true;await nextTick();(list.value?.querySelector('[aria-selected="true"]:not(:disabled)') as HTMLElement|null)?.focus();}
function pick(value:string){emit('update:modelValue',value);close(true);}
function key(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);return;}const els=[...(list.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')||[])];const i=els.indexOf(document.activeElement as HTMLButtonElement);if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?els.length-1:(i+(event.key==='ArrowDown'?1:-1)+els.length)%els.length;els[next]?.focus();}if(event.key==='Tab')close();}
function outside(event:PointerEvent){if(!root.value?.contains(event.target as Node))close();}
onMounted(()=>document.addEventListener('pointerdown',outside));onBeforeUnmount(()=>document.removeEventListener('pointerdown',outside));
</script>
<template><div ref="root" class="template-picker" @keydown="key"><button ref="trigger" type="button" :disabled="disabled" aria-label="完整模板目录" aria-haspopup="listbox" :aria-controls="id" :aria-expanded="open" @click="open?close():show()" @keydown.down.prevent="show()">{{selected}} <span aria-hidden="true">⌄</span></button><div v-if="open" :id="id" ref="list" class="template-menu" role="listbox" aria-label="模板目录"><button type="button" role="option" :aria-selected="!modelValue" @click="pick('')">空白文章</button><button v-for="item in options" :key="item.id" type="button" role="option" :aria-selected="modelValue===item.id" :disabled="item.is_folder" :style="{paddingLeft:12+item.depth*16+'px'}" @click="pick(item.id)">{{item.is_folder?'▸ ':''}}{{item.title}}</button></div></div></template>
<style scoped>.template-picker{position:relative;min-width:0}.template-picker>button{width:100%;display:flex;justify-content:space-between;gap:12px}button{min-height:38px;background:var(--bg-raised);color:var(--text-hi);border:1px solid #ffffff22;border-radius:7px;padding:8px 12px;font:inherit;text-align:left;cursor:pointer;overflow-wrap:anywhere}.template-menu{position:absolute;top:calc(100% + 5px);left:0;right:0;z-index:4;max-height:240px;overflow:auto;background:var(--bg-raised);border:1px solid #ffffff24;border-radius:8px;padding:4px;box-shadow:0 8px 24px #0006}.template-menu button{display:block;width:100%;border:0;background:transparent}.template-menu button[aria-selected=true]{color:var(--accent);background:var(--selected-bg,var(--bg-panel))}button:disabled{opacity:.6;cursor:default}.template-menu button:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}</style>
